{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Mithramycin, a glycosylated antitumor polyketide with the highest transfer score, showed a CSF:plasma ratio of only 0.12 in monkeys and little brain distribution, indicating that large glycosylated natural products of this class can have poor CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Digitoxin, a cardiac glycoside, exhibited a very low CSF/plasma ratio (0.01-0.03) in dogs, demonstrating that glycosidic natural products do not necessarily achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "SC-4453, another cardiac glycoside, had the lowest brain concentration among tissues at steady state in guinea pigs, consistent with a functional BBB barrier to glycosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "OPC-14117 was detected in human CSF in a dose-dependent manner, showing that some lipophilic, moderately sized molecules with methoxyphenyl/amine motifs can achieve CNS exposure.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "Emodin-8-O-β-D-glucoside, an anthraquinone glycoside, distributed into rat brain in a dose-dependent manner, suggesting that certain glycosides can cross the BBB.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C04"],
      "claim": "CMT-3, a lipophilic tetracycline, accumulated in rat brain at 4 µg/g, providing evidence that lipophilic polycyclic antibiotics can achieve meaningful brain exposure.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted fail: the query is daunorubicin, an anthracycline glycoside and known P-glycoprotein substrate. The strongest-transfer glycoside/antitumor-antibiotic evidence (mithramycin) and cardiac glycoside data indicate poor CNS access, while the supportive glycoside brain-penetration records come from structurally distinct flavonoids/iridoids and are outweighed by the known efflux liability of anthracyclines.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for daunorubicin is present in the provided evidence set.",
    "All Morgan similarities are below 0.25, limiting structural transferability.",
    "P-glycoprotein efflux status is not directly measured in the evidence records.",
    "Supportive glycoside CNS data come from different structural classes and may involve hydrolysis, prodrug effects, or transporter-mediated uptake not applicable to daunorubicin."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

